{"packet_id": "D024-01", "doc_id": "D024", "jurisdiction": "CA", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Tenant Protection Act annual rent increase cap", "requirement": "An owner may not increase the gross rental rate for a dwelling or unit by more than 5 percent plus the percentage change in the cost of living, or 10 percent, whichever is lower, over any 12-month period.", "key_value": "5% + CPI, max 10% per 12-month period", "coverage_conditions": "Residential real property, including dwellings and units in mobilehome parks, subject to subdivision (a); a new tenancy’s initial rent is set freely, with the cap applying only to later increases.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": "certificate_of_occupancy", "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "Deed-restricted affordable housing; dormitories; housing under public rent or price control with lower annual increases; housing with a certificate of occupancy within the previous 15 years; separately alienable homes owned by natural persons with written notice; owner-occupied duplexes.", "penalty": "An owner who demands, accepts, receives or retains rent above the maximum is liable for injunctive relief, the amount of the overcharge, attorney’s fees and costs, and up to three times the overcharge for willful conduct; the Attorney General and local counsel may enforce.", "effective_date": "2024-04-01", "citation": "Cal. Civ. Code § 1947.12", "quoted_span": "(a) (1) Subject to subdivision (b), an owner of residential real property shall not, over the course of any 12-month period, increase the gross rental rate for a dwelling or a unit more than 5 percent plus the percentage change in the cost of living, or 10 percent, whichever is lower, of the lowest gross rental rate charged for that dwelling or unit at any time during the 12 months prior to the effective date of the increase.", "interaction": "Does not authorize local rent increase limits beyond Chapter 2.7 and does not affect local authority to adopt or maintain rent control.", "confidence": 0.95, "conflict_flag": true, "conflict_note": "Subdivision (h) applies the cap to increases occurring on or after March 15, 2019, while subdivision (n) states the section became operative April 1, 2024."}
{"packet_id": "D024-01", "doc_id": "D024", "jurisdiction": "CA", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Limit of two rent increases in any 12-month period", "requirement": "If the same tenant remains in occupancy over a 12-month period, the owner may not increase the gross rental rate for that unit in more than two increments during that period.", "key_value": "2 increases per 12-month period", "coverage_conditions": "A unit of residential real property where the same tenant remains in lawful occupancy over any 12-month period, subject to the other restrictions of subdivision (a).", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": "certificate_of_occupancy", "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "Does not restrict the initial rental rate established for a new tenancy in which no tenant from the prior tenancy remains in lawful possession.", "penalty": "An owner who demands, accepts, receives or retains rent above the maximum allowed is liable for injunctive relief, the amount of the overcharge, attorney’s fees and costs, and up to three times the overcharge for willful conduct.", "effective_date": "2024-04-01", "citation": "Cal. Civ. Code § 1947.12: no more than two increases in 12 months", "quoted_span": "(2) If the same tenant remains in occupancy of a unit of residential real property over any 12-month period, the gross rental rate for the unit of residential real property shall not be increased in more than two increments over that 12-month period, subject to the other restrictions of this subdivision governing gross rental rate increase.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
